      logEvent('Canon state transition', id, `${record.name}: ${result.review.fromState} → ${nextState} · ${actor.name} (${actor.role}) · ${rationale}`);
      setNotice(`${record.name}: transition to ${nextState} recorded for ${actor.name}.`);
